    "source": "def knapsack_branch_and_bound(weights: list[int], values: list[int], W: int) -> int:\n    \"\"\"0-1 knapsack branch-and-bound (density bound) — complete Python reference.\"\"\"\n    n = len(weights)\n    order = sorted(range(n), key=lambda i: -values[i] / weights[i])\n    best = 0\n\n    def bound(i: int, rem_w: int, cur: float) -> float:\n        b = cur\n        w = rem_w\n        for k in range(i, n):\n            idx = order[k]\n            if weights[idx] <= w:\n                w -= weights[idx]\n                b += values[idx]\n            else:\n                b += values[idx] / weights[idx] * w\n                break\n        return b\n\n    def dfs(i: int, rem_w: int, cur: int) -> None:\n        nonlocal best\n        if i == n:\n            if cur > best:\n                best = cur\n            return\n        if bound(i, rem_w, cur) <= best:\n            return\n        idx = order[i]\n        if weights[idx] <= rem_w:\n            dfs(i + 1, rem_w - weights[idx], cur + values[idx])\n        dfs(i + 1, rem_w, cur)\n\n    dfs(0, W, 0)\n    return best\n",
