    "source": "// 0-1 knapsack branch-and-bound (density bound) — complete C++17 reference.\n#include <algorithm>\n#include <functional>\n#include <numeric>\n#include <vector>\n\nlong long knapsackBranchAndBound(const std::vector<int>& weights, const std::vector<long long>& values, int W) {\n    int n = static_cast<int>(weights.size());\n    std::vector<int> order(n);\n    std::iota(order.begin(), order.end(), 0);\n    std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return 1.0 * values[a] / weights[a] > 1.0 * values[b] / weights[b]; });\n    long long best = 0;\n    auto bound = [&](int i, int remW, long long cur) -> double {\n        double b = cur;\n        int w = remW;\n        for (int k = i; k < n; k++) {\n            int idx = order[k];\n            if (weights[idx] <= w) {\n                w -= weights[idx];\n                b += values[idx];\n            } else {\n                b += 1.0 * values[idx] / weights[idx] * w;\n                break;\n            }\n        }\n        return b;\n    };\n    std::function<void(int, int, long long)> dfs = [&](int i, int remW, long long cur) {\n        if (i == n) {\n            if (cur > best) best = cur;\n            return;\n        }\n        if (bound(i, remW, cur) <= best) return;\n        int idx = order[i];\n        if (weights[idx] <= remW) dfs(i + 1, remW - weights[idx], cur + values[idx]);\n        dfs(i + 1, remW, cur);\n    };\n    dfs(0, W, 0);\n    return best;\n}\n",
