    "source": "/// 0-1 knapsack branch-and-bound (density bound) — complete Rust reference (capacity W is `cap`).\npub fn knapsack_branch_and_bound(weights: &[usize], values: &[i64], cap: usize) -> i64 {\n    struct Ctx<'a> {\n        weights: &'a [usize],\n        values: &'a [i64],\n        order: Vec<usize>,\n        best: i64,\n    }\n    fn bound(c: &Ctx, i: usize, rem_w: usize, cur: i64) -> f64 {\n        let mut b = cur as f64;\n        let mut w = rem_w;\n        for k in i..c.order.len() {\n            let idx = c.order[k];\n            if c.weights[idx] <= w {\n                w -= c.weights[idx];\n                b += c.values[idx] as f64;\n            } else {\n                b += c.values[idx] as f64 / c.weights[idx] as f64 * w as f64;\n                break;\n            }\n        }\n        b\n    }\n    fn dfs(c: &mut Ctx, i: usize, rem_w: usize, cur: i64) {\n        if i == c.order.len() {\n            if cur > c.best {\n                c.best = cur;\n            }\n            return;\n        }\n        if bound(c, i, rem_w, cur) <= c.best as f64 {\n            return;\n        }\n        let idx = c.order[i];\n        if c.weights[idx] <= rem_w {\n            dfs(c, i + 1, rem_w - c.weights[idx], cur + c.values[idx]);\n        }\n        dfs(c, i + 1, rem_w, cur);\n    }\n    let density = |i: usize| values[i] as f64 / weights[i] as f64;\n    let mut order: Vec<usize> = (0..weights.len()).collect();\n    order.sort_by(|&a, &b| density(b).total_cmp(&density(a)));\n    let mut c = Ctx { weights, values, order, best: 0 };\n    dfs(&mut c, 0, cap, 0);\n    c.best\n}\n",
